package com.aryak;

import org.gradle.api.Project;
import org.gradle.testfixtures.ProjectBuilder;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static com.aryak.CoverageDefaults.COVERAGE_LOCK_FILE;
import static com.aryak.CoverageDefaults.GOAL;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * A simple unit test for the 'org.example.greeting' plugin.
 */
class CoveragePluginTest {

    @Test
    void pluginRegistersATask() {
        // Create a test project and apply the plugin
        Project project = ProjectBuilder.builder().build();
        project.getPlugins().apply("com.aryak.coveragelock");

        // Verify the result
        assertNotNull(project.getTasks().findByName("greeting"));
    }

    @Test
    @DisplayName(value = "Check if the extension is registered correctly")
    void pluginRegistersAnExtension() {
        // Create a test project and apply the plugin
        Project project = ProjectBuilder.builder().build();
        project.getPlugins().apply("com.aryak.coveragelock");

        // Verify the result
        assertNotNull(project.getExtensions().getByName("coverageLock"));
    }

    @Test
    @DisplayName(value = "Check if the extension has correct defaults")
    void pluginRegistersAnExtensionWithCorrectDefaultConfiguration() {
        // Create a test project and apply the plugin
        Project project = ProjectBuilder.builder().build();
        project.getPlugins().apply("com.aryak.coveragelock");

        // Verify the result
        CoverageLock extension = (CoverageLock) project.getExtensions().getByName("coverageLock");
        assertEquals(GOAL, extension.getGoal());
        assertEquals(COVERAGE_LOCK_FILE, extension.getResultFile().getName());
    }
}
